import { LinkedFunctionGradientExplorer, STANDARD_FUNCTIONS } from './linked-function-gradient-explorer.js';
const IDS=new Set(['activity:y13:differentiation:standard-functions:understand:graph-discovery','activity:y13:differentiation:standard-functions:understand:scaled-functions','activity:y13:differentiation:standard-functions:understand:mixed-comparison']);
function el(d,t,c='',x=''){const n=d.createElement(t);if(c)n.className=c;if(x)n.textContent=x;return n;}
export class StandardFunctionsUnderstandExperience{
 constructor(host){if(!host)throw new Error('StandardFunctionsUnderstandExperience requires a host.');this.host=host;this.document=host.ownerDocument||document;this.explorer=null;}
 supports(id){return IDS.has(id);} destroy(){this.explorer?.destroy();this.explorer=null;this.host.replaceChildren();this.host.classList.remove('standard-functions-understand');}
 render(id){if(!this.supports(id))return false;this.destroy();this.host.classList.add('standard-functions-understand');const slug=id.split(':').at(-1);this[`render_${slug.replaceAll('-','_')}`]();return true;}
 panel(title,instruction){const p=el(this.document,'section','standard-functions-understand__panel');const h=el(this.document,'div','standard-functions-understand__header');h.append(el(this.document,'div','standard-functions-understand__radians','RADIAN MODE'),el(this.document,'h3','',title),el(this.document,'p','',instruction));const g=el(this.document,'div','standard-functions-understand__graph');p.append(h,g);this.host.append(p);return {p,g};}
 mount(g,functions,options={}){this.explorer=new LinkedFunctionGradientExplorer(g,{functions,allowSecondDerivative:false,revealDerivative:false,showDerivativeReadout:true,...options});return this.explorer;}
 render_graph_discovery(){const {p,g}=this.panel('Predict the gradient function before you reveal it','Move the point along sin x, cos x, e^x and ln x. Compare the tangent gradient with the corresponding derivative height.');const note=el(this.document,'p','standard-functions-understand__note','For sin and cos, these rules work in radians.');p.insertBefore(note,g);this.mount(g,STANDARD_FUNCTIONS.filter(f=>['sin-x','cos-x','exp-x','ln-x'].includes(f.id)),{derivativePanelVisible:true});}
 render_scaled_functions(){const {p,g}=this.panel('What does the input scale do?','Compare scaled forms. Look at the numerical tangent gradient before revealing f′(x).');const note=el(this.document,'p','standard-functions-understand__note','Notice: ln(ax) still has derivative 1/x for positive a; for a^(kx), the multiplier is k ln(a).');p.insertBefore(note,g);this.mount(g,STANDARD_FUNCTIONS.filter(f=>['sin-2x','cos-3x','exp-2x','ln-2x','two-3x'].includes(f.id)),{derivativePanelVisible:true});}
 render_mixed_comparison(){const {p,g}=this.panel('One relationship across every standard function','Switch functions and test several x-values. The tangent slope, numerical gradient and derivative-graph height should agree.');const status=el(this.document,'div','standard-functions-understand__status','Move the point and then reveal the derivative curve.');p.insertBefore(status,g);this.mount(g,STANDARD_FUNCTIONS,{derivativePanelVisible:true,onChange:({values})=>{status.textContent=`Current tangent gradient = ${Number(values.derivative.toFixed(3))}. The derivative graph uses the same value.`;}});}
}
export function createStandardFunctionsUnderstandExperience(host,options){return new StandardFunctionsUnderstandExperience(host,options);}
